<script lang="ts">
 import {onMount,untrack}from'svelte';import{fade}from'svelte/transition';import{prefersReducedMotion}from'svelte/motion';import{Citrus,Cherry,Flower2,Leaf,Apple,Sparkles,ArrowRight,Sun,ShieldCheck,Thermometer}from'lucide-svelte';import Glass from'./Glass.svelte';import RegionMap from'./RegionMap.svelte';
 let{kind,slug}:{kind:string;slug:string}=$props();let root:HTMLElement;let skin=$state(untrack(()=>slug==='rotwein'?'red':slug==='weisswein'?'white':'rose'));let aroma=$state(0);let sharp=$state(true);let closure=$state('cork');let process=$state(1);let label=$state(0);let pinot=$state(untrack(()=>slug==='weissburgunder'?2:slug==='spaetburgunder'?0:1));
 const skinOptions=[{id:'white',name:'Hell',color:'#e3dba9',title:'Saft früh von den Schalen trennen',body:'Dunkle Trauben können einen hellen Wein ergeben. Bei Blanc de Noirs gelangt möglichst wenig Farbe aus den Schalen in den Saft.'},{id:'rose',name:'Rosé',color:'#dfa09d',title:'Kurzer Kontakt mit den dunklen Schalen',body:'Ein Teil der Farbe löst sich im Saft. Anschließend wird er von den festen Traubenteilen getrennt. So entsteht die Grundidee eines Rosés.'},{id:'red',name:'Rot',color:'#944960',title:'Mit den dunklen Schalen vergären',body:'Während der Maischegärung lösen sich Farbe und Gerbstoffe. Wie kräftig das Ergebnis wird, hängt auch von den Trauben und dem Verfahren ab.'}];const selectedSkin=$derived(skinOptions.find(x=>x.id===skin)!);
 const aromaOptions=[{name:'Zitrus',icon:Citrus,words:['Zitrone','Grapefruit','Limette'],text:'Eine Fruchtfamilie ist ein guter Anfang. Ob du an frische Schale, Saft oder reife Frucht denkst, darfst du selbst beschreiben.'},{name:'Helle Frucht',icon:Apple,words:['Apfel','Birne','Pfirsich'],text:'Diese Früchte begegnen oft in Weißweinbeschreibungen. Ein solcher Duft bedeutet nicht automatisch, dass der Wein süß schmeckt.'},{name:'Rote Frucht',icon:Cherry,words:['Erdbeere','Kirsche','Himbeere'],text:'Rote Früchte werden häufig bei Rosé und Rotwein beschrieben. Welche davon du wahrnimmst, hängt vom einzelnen Wein ab.'},{name:'Blüten',icon:Flower2,words:['Rose','Akazie','Holunderblüte'],text:'Blumig ist bereits eine brauchbare Beobachtung. Es ist nicht nötig, jede einzelne Blüte sicher benennen zu können.'},{name:'Kräuter',icon:Leaf,words:['Gras','Heu','Kräuter'],text:'Pflanzliche Eindrücke gehören ebenfalls zum Wein. Der Vergleich mit etwas Bekanntem hilft mehr als ein besonders kompliziertes Wort.'},{name:'Würze',icon:Sparkles,words:['Pfeffer','Vanille','Nelke'],text:'Würzige Eindrücke können aus unterschiedlichen Einflüssen stammen. Vanille kann etwa mit Holzausbau zusammenhängen, ist aber keine Zutatenangabe.'}];
 const pinots=[{name:'Spätburgunder',other:'Pinot Noir',color:'#6c455e',text:'Dunkle Beeren. Für Rotwein, Rosé oder einen hellen Blanc de Noirs geeignet.'},{name:'Grauburgunder',other:'Pinot Gris / Grigio',color:'#bc9492',text:'Graurosa bis rötliche Beeren. Meist als Weißwein ausgebaut.'},{name:'Weißburgunder',other:'Pinot Blanc / Bianco',color:'#bfc78c',text:'Helle Beeren. Eine eigene Sorte innerhalb der Pinot-Familie.'}];
 const stages=[{title:'Pressen',label:'Aus Trauben wird Most',text:'Most ist Traubensaft vor oder während der Gärung. Bei der üblichen Weißweinbereitung werden die Schalen früh vom Saft getrennt.'},{title:'Gären',label:'Hefe wandelt Zucker um',text:'Bei der alkoholischen Gärung entstehen Alkohol, Kohlendioxid und Wärme. Im Stillwein darf das Gas weitgehend entweichen.'},{title:'Ausbauen',label:'Der Wein entwickelt sich weiter',text:'Tank oder Fass, Zeit und Hefekontakt beeinflussen den Wein. Ausbau bezeichnet die Entscheidungen in dieser Phase.'}];
 const labelParts=[{title:'Wer?',value:'Margarethenhof',text:'Der Betrieb hinter dem Wein.'},{title:'Woher?',value:'Ayler',text:'Ayl ist der Weinort. Das übergeordnete Anbaugebiet heißt Mosel, der Bereich Saar.'},{title:'Welche Traube?',value:'Riesling',text:'Die Rebsorte. Sie kann trocken, feinherb oder süß ausgebaut werden.'},{title:'Welcher Stil?',value:'feinherb',text:'Eine Geschmacksangabe ohne festgelegte Restzuckerspanne.'}];
 onMount(()=>{const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){root.classList.add('visual-visible');observer.disconnect();}},{threshold:.2});observer.observe(root);return()=>observer.disconnect();});
</script>
<div class="learning-visual" bind:this={root} data-visual={kind}>
{#if kind==='region'}<RegionMap {slug}/>
{:else if kind==='skins'}
 <div class="visual-heading"><span class="eyebrow">FARBE AUS DER SCHALE</span><h3>Eine dunkle Traube. Drei Möglichkeiten.</h3></div>
 <div class="diagram-options" role="group" aria-label="Weinbereitung vergleichen">{#each skinOptions as option}<button type="button" aria-pressed={skin===option.id} class:active={skin===option.id} onclick={()=>skin=option.id}><span style={'background:'+option.color}></span>{option.name}</button>{/each}</div>
 <div class="skin-diagram" aria-hidden="true"><svg viewBox="0 0 120 140" class="grape-diagram"><path d="M63 25Q59 8 75 6M63 24Q38 6 25 26Q48 41 63 24" fill="none" stroke="currentColor" stroke-width="2"/>{#each [[43,47],[68,43],[88,58],[49,72],[73,72],[91,85],[59,96],[77,104],[66,123]] as [x,y]}<circle cx={x} cy={y} r="14" fill="#73516a" stroke="var(--visual-surface)" stroke-width="2"/>{/each}</svg><div class="process-connector"><span></span><ArrowRight size={22}/><small>Schalenkontakt</small></div><Glass color={selectedSkin.color}/></div>
 {#key skin}<div class="visual-explanation" in:fade={{duration:prefersReducedMotion.current?0:130}}><h4>{selectedSkin.title}</h4><p>{selectedSkin.body}</p></div>{/key}<small class="visual-caption">Vereinfachtes Prinzip. Keine feste Zeitangabe für eine bestimmte Abfüllung.</small>
{:else if kind==='bubbles'}
 <div class="visual-heading"><span class="eyebrow">DER DRUCK MACHT DEN UNTERSCHIED</span><h3>Von still bis prickelnd.</h3></div>
 <div class="pressure-comparison">{#each [{title:'Stillwein',amount:0,text:'Ohne Perlwein-Druck',detail:'Die Kohlensäure der Gärung entweicht weitgehend.'},{title:'Secco',amount:4,text:'1–2,5 bar',detail:'Perlwein. Kohlensäure kann zugesetzt werden.'},{title:'Sekt',amount:10,text:'Ab 3,5 bar',detail:'Die Kohlensäure entsteht durch Gärung.'}] as item}<div><Glass color={item.title==='Secco'?'#dfa09d':'#dfd49c'} bubbles={item.amount}/><h4>{item.title}</h4><strong>{item.text}</strong><p>{item.detail}</p></div>{/each}</div><small class="visual-caption">Überdruck in der geschlossenen Flasche bei 20 °C. Die Zeichnung vergleicht das Prinzip.</small>
{:else if kind==='aromas'}
 <div class="visual-heading"><span class="eyebrow">VOM GROBEN ZUM GENAUEREN</span><h3>Woran erinnert dich der Duft?</h3></div>
 <div class="aroma-families" role="group" aria-label="Duftfamilie auswählen">{#each aromaOptions as option,i}<button type="button" aria-pressed={aroma===i} class:active={aroma===i} onclick={()=>aroma=i}><option.icon size={26} strokeWidth={1.5}/><span>{option.name}</span></button>{/each}</div>
 {#key aroma}<div class="aroma-examples" in:fade={{duration:prefersReducedMotion.current?0:130}}><div>{#each aromaOptions[aroma].words as word}<span>{word}</span>{/each}</div><p>{aromaOptions[aroma].text}</p></div>{/key}<small class="visual-caption">Wortschatz zum Riechen. Keine Zutatenliste und keine Pflichtaromen.</small>
{:else if kind==='pinot'}
 <div class="visual-heading"><span class="eyebrow">DIE PINOT-FAMILIE</span><h3>Verwandte Trauben, verschiedene Farben.</h3></div><div class="pinot-family" role="group" aria-label="Burgundersorte auswählen">{#each pinots as item,i}<button type="button" aria-pressed={pinot===i} class:active={pinot===i} onclick={()=>pinot=i}><svg viewBox="0 0 90 105" aria-hidden="true"><path d="M45 23Q43 7 61 5" fill="none" stroke="currentColor" stroke-width="2"/>{#each [[29,37],[52,34],[70,47],[32,62],[57,62],[45,86]] as [x,y]}<circle cx={x} cy={y} r="15" fill={item.color} stroke="var(--visual-surface)" stroke-width="2"/>{/each}</svg><strong>{item.name}</strong><small>{item.other}</small></button>{/each}</div><p class="visual-explanation">{pinots[pinot].text}</p><small class="visual-caption">Die Verbindungen zeigen die Pinot-Familie, keine Qualitätsrangfolge.</small>
{:else if kind==='balance'}
 <div class="visual-heading"><span class="eyebrow">SÜSSE UND SÄURE WIRKEN ZUSAMMEN</span><h3>Gleiche Süße kann anders wirken.</h3></div><div class="diagram-options" role="group" aria-label="Säureeindruck vergleichen"><button type="button" aria-pressed={sharp} class:active={sharp} onclick={()=>sharp=true}>Mehr Säure</button><button type="button" aria-pressed={!sharp} class:active={!sharp} onclick={()=>sharp=false}>Weniger Säure</button></div><div class="balance-bars"><div><span>Restzucker</span><div><span class="sugar-bar" style="width:65%"></span></div><small>bleibt gleich</small></div><div><span>Säure</span><div><span class="acid-bar" style:width={sharp?'80%':'35%'}></span></div><small>{sharp?'deutlicher':'zurückhaltender'}</small></div></div><div class="visual-explanation"><h4>{sharp?'Die Säure kann die Süße ausgleichen.':'Die Süße kann deutlicher hervortreten.'}</h4><p>Wie süß ein Wein wirkt, hängt vom Zusammenspiel seiner Bestandteile ab. Fruchtiger Duft und süßer Geschmack bleiben verschiedene Dinge.</p></div><small class="visual-caption">Schema ohne Messwerte. Kein berechnetes Geschmacksprofil unseres Rieslings.</small>
{:else if kind==='fermentation'}
 <div class="visual-heading"><span class="eyebrow">VOM SAFT ZUM WEIN</span><h3>Was im Keller passiert.</h3></div><div class="production-steps" role="group" aria-label="Schritt der Weinbereitung auswählen">{#each stages as item,i}<button type="button" aria-pressed={process===i} class:active={process===i} onclick={()=>process=i}><span>0{i+1}</span><strong>{item.title}</strong>{#if i<2}<ArrowRight size={17}/>{/if}</button>{/each}</div><div class="fermentation-equation"><span>Traubenzucker</span><span class="equation-arrow"><ArrowRight size={22}/><small>Hefe</small></span><div><strong>Alkohol + CO₂</strong><small>Bei der Gärung entsteht auch Wärme.</small></div></div>{#key process}<div class="visual-explanation" in:fade={{duration:prefersReducedMotion.current?0:130}}><h4>{stages[process].label}</h4><p>{stages[process].text}</p></div>{/key}
{:else if kind==='closures'}
 <div class="visual-heading"><span class="eyebrow">ZWEI VERSCHLÜSSE</span><h3>Der Inhalt entscheidet.</h3></div><div class="closure-comparison" role="group" aria-label="Verschluss vergleichen"><button type="button" class:active={closure==='cork'} aria-pressed={closure==='cork'} onclick={()=>closure='cork'}><svg viewBox="0 0 120 140" aria-hidden="true"><rect x="37" y="24" width="46" height="92" rx="11" fill="#b99b74"/><path d="M45 39h10m10 12h10M47 66h17m5 20h8M46 99h9" stroke="#705a43" stroke-width="2" stroke-linecap="round"/><ellipse cx="60" cy="28" rx="22" ry="7" fill="#d9bd91"/></svg><strong>Naturkork</strong></button><button type="button" class:active={closure==='screw'} aria-pressed={closure==='screw'} onclick={()=>closure='screw'}><svg viewBox="0 0 120 140" aria-hidden="true"><rect x="32" y="38" width="56" height="67" rx="6" fill="#879b86"/><ellipse cx="60" cy="38" rx="28" ry="9" fill="#b4c5ae"/><path d="M34 70h52M34 83h52M34 95h52" stroke="#405c46" stroke-width="1.5"/></svg><strong>Schraubverschluss</strong></button></div><div class="visual-explanation"><h4>{closure==='cork'?'Aus der Rinde der Korkeiche':'Praktisch zu öffnen und wieder zu schließen'}</h4><p>{closure==='cork'?'Korkkrümel sind kein Beweis für einen Korkfehler. Korkton ist ein Geruchsproblem und kann an feuchte Pappe erinnern.':'Auch hochwertige Weine können einen Schraubverschluss haben. Material und Dichtung werden passend zum gewünschten Wein gewählt.'}</p></div>
{:else if kind==='temperature'}
 <div class="visual-heading"><span class="eyebrow">ORIENTIERUNG IM GLAS</span><h3>Kühl ist nicht bei jedem Wein gleich.</h3></div><div class="temperature-ranges">{#each [{name:'Secco',range:'6–8 °C',from:6,to:8,color:'var(--viz-rose)'},{name:'JUWEL Grauburgunder',range:'10–12 °C',from:10,to:12,color:'var(--viz-gold)'},{name:'Viele Rotweine',range:'16–18 °C',from:16,to:18,color:'var(--viz-red)'}] as item}<div><span>{item.name}</span><strong>{item.range}</strong><div class="temperature-track"><span style={'left:'+(item.from/22*100)+'%;width:'+((item.to-item.from)/22*100)+'%;background:'+item.color}></span></div></div>{/each}</div><p class="visual-caption">Empfehlungen als Ausgangspunkt. Der Wein und dein Geschmack entscheiden; am Tisch wird der Wein wärmer.</p>
{:else if kind==='label'}
 <div class="visual-heading"><span class="eyebrow">EIN ETIKETT ENTSCHLÜSSELN</span><h3>Vier Fragen an die Flasche.</h3></div><div class="label-demo"><div class="sample-label"><small>BEISPIEL AUS UNSEREM TASTING</small>{#each labelParts as item,i}<span class:highlighted={label===i}>{item.value}</span>{/each}<em>Schieferstein</em></div><div><div class="label-questions" role="group" aria-label="Etikettangabe auswählen">{#each labelParts as item,i}<button type="button" aria-pressed={label===i} class:active={label===i} onclick={()=>label=i}>{item.title}</button>{/each}</div><p>{labelParts[label].text}</p></div></div><small class="visual-caption">Vereinfachtes Lese-Beispiel, keine Nachbildung des Originaletiketts.</small>
{:else if kind==='storage'}
 <div class="visual-heading"><span class="eyebrow">EIN GUTER PLATZ FÜR WEIN</span><h3>Drei Dinge helfen beim Aufbewahren.</h3></div><div class="storage-principles">{#each [{icon:Sun,title:'Dunkel',text:'Vor direktem Licht schützen.'},{icon:Thermometer,title:'Kühl',text:'Wärmequellen vermeiden.'},{icon:ShieldCheck,title:'Gleichmäßig',text:'Wenig Temperatursprünge und Erschütterungen.'}] as item}<div><item.icon size={30} strokeWidth={1.4}/><h4>{item.title}</h4><p>{item.text}</p></div>{/each}</div>
{/if}
</div>
